/**
 * Generates `docs/demos/<slug>.gen.tsx` from the inline demo components each
 * docs MDX page defines at module level (see
 * `scripts/shared/extract-inline-demos.ts` for why they must move for the
 * published pages). The generated modules become tsup entries
 * (`dist/docs/demos/<slug>.js`, client modules via the shared banner) that
 * the published MDX imports as `@hashintel/ds-components/docs/demos/<slug>`.
 *
 * Runs before `build:lib:js`. The generated files are excluded from tsc —
 * inline MDX components were never type-checked — and are validated instead
 * by the esbuild compile plus `generate-docs-mdx`'s render verification.
 */
import {
  globSync,
  mkdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";

import { collectCompoundMemberUsages } from "./shared/compound-member-usages";
import { extractInlineDemos } from "./shared/extract-inline-demos";

import type { CompoundMemberUsage } from "./shared/compound-member-usages";

const outDir = path.join("docs", "demos");

/** Rewrites a page-relative import specifier to be relative to docs/demos. */
const rewriteSpecifier = (specifier: string, componentDir: string): string => {
  const blocksMatch = /^(?:\.\.\/)+docs\/blocks\/(.+)$/.exec(specifier);
  if (blocksMatch) {
    return `../blocks/${blocksMatch[1]}`;
  }
  const utilMatch = /^(?:\.\.\/)+util\/(.+)$/.exec(specifier);
  if (utilMatch) {
    return `../../src/util/${utilMatch[1]}`;
  }
  if (specifier.startsWith("./")) {
    return `../../src/components/${componentDir}/${specifier.slice(2)}`;
  }
  if (specifier.startsWith("../")) {
    return `../../src/components/${specifier.slice(3)}`;
  }
  return specifier;
};

rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });

let moduleCount = 0;
let demoCount = 0;
const compoundUsages = new Map<
  string,
  CompoundMemberUsage & { resolvedSpecifier: string }
>();
for (const file of globSync("src/components/*/*.docs.mdx").sort()) {
  const slug = path.basename(file, ".docs.mdx");
  const componentDir = path.basename(path.dirname(file));
  const source = readFileSync(file, "utf8");
  const extraction = extractInlineDemos(source);

  // Compound member usages are collected from the page as published (i.e.
  // with the inline demos removed — usages inside those are fine, they
  // compile as client code).
  const lines = source.split("\n");
  const dropped = new Set<number>();
  for (const block of extraction.moved) {
    for (let index = block.startLine; index < block.endLine; index += 1) {
      dropped.add(index);
    }
  }
  const publishedBody = lines
    .filter((_, index) => !dropped.has(index))
    .join("\n");
  for (const usage of collectCompoundMemberUsages(publishedBody)) {
    const resolvedSpecifier = rewriteSpecifier(
      usage.baseSpecifier,
      componentDir,
    );
    const existing = compoundUsages.get(usage.dotted);
    if (existing && existing.resolvedSpecifier !== resolvedSpecifier) {
      throw new Error(
        `\`${usage.dotted}\` resolves to different modules across pages`,
      );
    }
    compoundUsages.set(usage.dotted, { ...usage, resolvedSpecifier });
  }

  if (extraction.moved.length === 0) {
    continue;
  }

  const imports = extraction.headerImports.map((statement) =>
    statement.replace(
      /from "([^"]+)";/,
      (_match, specifier: string) =>
        `from "${rewriteSpecifier(specifier, componentDir)}";`,
    ),
  );

  writeFileSync(
    path.join(outDir, `${slug}.gen.tsx`),
    `// Generated by \`scripts/generate-docs-demos.ts\` from ${file} — do not edit.
// Inline demo components for the published \`${slug}\` docs page: they use
// hooks and inline functions, so the (server-compiled) published MDX imports
// them from this client module instead of defining them inline.
${imports.join("\n")}

${extraction.moved.map((block) => block.text).join("\n\n")}
`,
  );
  moduleCount += 1;
  demoCount += extraction.moved.length;
}

// Compound members (`Banner.ActionButton`, `Dialog.Body`, …) flattened into a
// client module: property access through a client *reference* does not
// resolve in the server-compiled published MDX, so the pages import these
// flat bindings instead (rewritten by generate-docs-mdx.ts).
if (compoundUsages.size > 0) {
  const byBase = new Map<string, string>();
  for (const usage of compoundUsages.values()) {
    const existing = byBase.get(usage.base);
    if (existing !== undefined && existing !== usage.resolvedSpecifier) {
      throw new Error(`base \`${usage.base}\` has conflicting modules`);
    }
    byBase.set(usage.base, usage.resolvedSpecifier);
  }
  const imports = [...byBase.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([base, specifier]) => `import { ${base} } from "${specifier}";`);
  const exports = [...compoundUsages.values()]
    .sort((a, b) => a.flat.localeCompare(b.flat))
    .map((usage) => `export const ${usage.flat} = ${usage.dotted};`);
  writeFileSync(
    path.join(outDir, "compound-parts.gen.tsx"),
    `// Generated by \`scripts/generate-docs-demos.ts\` — do not edit.
// Compound-component members used by the published docs pages, flattened:
// the pages compile as server modules under RSC, where property access
// through a client component reference does not resolve.
${imports.join("\n")}

${exports.join("\n")}
`,
  );
  moduleCount += 1;
}

console.log(
  `Wrote ${moduleCount} demo modules (${demoCount} exports, ${compoundUsages.size} compound parts) to ${outDir}`,
);
